.ds-top-header{--night:#031315;--parchment:#fef6e1;--lantern:#efb83f;--horizon:#5e8bd6;--surface:var(--night);--ink:var(--parchment);--muted:#d5d3c5;--rule:color-mix(in srgb,var(--parchment) 27%,var(--night));--focus:var(--horizon);color:var(--ink);background:var(--surface);font:400 1rem/1.5 'Source Sans 3',system-ui,sans-serif;box-sizing:border-box;}.ds-top-header *{box-sizing:border-box}.ds-top-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 24px;
  padding: max(12px, env(safe-area-inset-top, 0px)) clamp(20px, 4.4vw, 64px) 12px;
  color: var(--parchment);
  background: var(--night);
  border-bottom: 1px solid var(--rule);
}
.ds-brand-identity {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
}
.ds-brand-identity img { width: 40px; height: 40px; flex-shrink: 0; }
.ds-brand-identity span {
  min-width: 0;
  font: 400 1.75rem/1.1 'IM Fell English SC', Georgia, serif;
  letter-spacing: -.02em;
}
.ds-primary-navigation {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 8px;
}
.ds-navigation-link {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 8px 10px;
  border-radius: 4px;
  text-decoration: none;
  overflow-wrap: anywhere;
}
.ds-navigation-link[aria-current='page'] { font-weight: 600; }
.ds-navigation-link[aria-current='page']::before {
  position: absolute;
  inset: auto 10px 4px;
  height: 2px;
  background: var(--horizon);
  content: '';
}
.ds-navigation-link:hover,
.ds-navigation-link:active { text-decoration: underline; }
.ds-navigation-link:focus-visible {
  outline-color: var(--horizon);
  outline-offset: -6px;
}@media(width < 56rem){.ds-top-header{padding-inline:20px}.ds-primary-navigation{gap:4px}}

.ds-notice{--night:#031315;--parchment:#fef6e1;--lantern:#efb83f;--horizon:#5e8bd6;--surface:var(--night);--ink:var(--parchment);--muted:#d5d3c5;--rule:color-mix(in srgb,var(--parchment) 27%,var(--night));--focus:var(--horizon);color:var(--ink);background:var(--surface);font:400 1rem/1.5 'Source Sans 3',system-ui,sans-serif;box-sizing:border-box;}.ds-notice{--ink:var(--night);--surface:var(--parchment);--rule:color-mix(in srgb,var(--night) 25%,var(--parchment));}.ds-notice {
  max-width: 42rem;
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--rule);
}
.ds-notice p { margin: .5rem 0 0; }.ds-notice h2{margin:0;font-size:1.125rem;font-weight:600;line-height:1.4}

.ds-content-link{--night:#031315;--parchment:#fef6e1;--lantern:#efb83f;--horizon:#5e8bd6;--surface:var(--night);--ink:var(--parchment);--muted:#d5d3c5;--rule:color-mix(in srgb,var(--parchment) 27%,var(--night));--focus:var(--horizon);color:var(--ink);background:var(--surface);font:400 1rem/1.5 'Source Sans 3',system-ui,sans-serif;box-sizing:border-box;}.ds-content-link {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  margin-top: 1rem;
  font-weight: 600;
  text-decoration-line: underline;
}
.ds-content-link {
  justify-content: center;
  padding: .625rem 1.25rem;
  border-radius: 5px;
  color: var(--night);
  background: var(--lantern);
  text-decoration: none;
}
.ds-content-link:hover { text-decoration: underline; }
.ds-content-link:active { background: var(--parchment); }.ds-content-link:focus-visible{outline:2px solid var(--horizon);outline-offset:4px}

.ds-recall-toolbar{--night:#031315;--parchment:#fef6e1;--lantern:#efb83f;--horizon:#5e8bd6;--surface:var(--night);--ink:var(--parchment);--muted:#d5d3c5;--rule:color-mix(in srgb,var(--parchment) 27%,var(--night));--focus:var(--horizon);color:var(--ink);background:var(--surface);font:400 1rem/1.5 'Source Sans 3',system-ui,sans-serif;box-sizing:border-box;}.ds-recall-toolbar {
  flex: 0 0 auto;
