}
.ds-recall-toolbar h1 { display: flex; align-items: center; min-height: 44px; margin-right: auto; }
.ds-read-only { margin: 0; font-size: .875rem; }.ds-recall-toolbar h1{font-size:1.75rem;font-weight:600;line-height:1.2}.ds-recall-toolbar p{margin:0;font-size:.875rem}@media(width < 56rem){.ds-recall-toolbar{padding:8px 20px}}

