.ds-files-toggle:hover { color: var(--surface); background: var(--ink); }
.ds-files-toggle:active { color: var(--night); background: var(--lantern); }.ds-files-toggle:focus-visible{outline:2px solid var(--horizon);outline-offset:4px}

.ds-reader-control-context{--night:#031315;--parchment:#fef6e1;--lantern:#efb83f;--horizon:#5e8bd6;--surface:var(--night);--ink:var(--parchment);--muted:#d5d3c5;--rule:color-mix(in srgb,var(--parchment) 27%,var(--night));--focus:var(--horizon);color:var(--ink);background:var(--surface);font:400 1rem/1.5 'Source Sans 3',system-ui,sans-serif;box-sizing:border-box;}.ds-reader-control-context{--surface:var(--parchment);--ink:var(--night);--focus:var(--night);min-height:100px;padding:1.75rem 2rem}.ds-reader-control-context [hidden]{display:none!important}.ds-files-control { position: relative; display: inline-flex; flex: 0 0 44px; }
