.ds-vault{--night:#031315;--parchment:#fef6e1;--lantern:#efb83f;--horizon:#5e8bd6;--surface:var(--night);--ink:var(--parchment);--muted:#d5d3c5;--rule:color-mix(in srgb,var(--parchment) 27%,var(--night));--focus:var(--horizon);color:var(--ink);background:var(--surface);font:400 1rem/1.5 'Source Sans 3',system-ui,sans-serif;box-sizing:border-box;}.ds-vault{padding:1.5rem 1rem 2rem}.ds-vault ul{list-style:none;margin:0;padding:0}.ds-vault ul ul{margin-left:.875rem}.ds-vault h2{margin:0 .5rem 1rem;font-size:1.125rem}.ds-file-row {
  display: flex;
  gap: .375rem;
  align-items: flex-start;
  width: 100%;
  min-width: 10rem;
  min-height: 44px;
  padding: .625rem .5rem;
  border: 0;
  border-radius: 0;
  text-align: left;
  color: var(--parchment);
  background: var(--night);
  line-height: 1.5;
  text-decoration: none;
  overflow-wrap: anywhere;
  cursor: pointer;
}
.ds-file-row span { min-width: 0; }
.ds-folder { font-weight: 600 !important; }
.ds-file-link { padding-left: 1.875rem; }
.ds-file-row:hover span { text-decoration: underline; }
.ds-file-link[aria-current='page'] span {
  font-weight: 600;
  text-decoration: underline;
  text-decoration-color: var(--horizon);
  text-decoration-thickness: 2px;
  text-underline-offset: .25em;
