.ds-reader{--night:#031315;--parchment:#fef6e1;--lantern:#efb83f;--horizon:#5e8bd6;--surface:var(--night);--ink:var(--parchment);--muted:#d5d3c5;--rule:color-mix(in srgb,var(--parchment) 27%,var(--night));--focus:var(--horizon);color:var(--ink);background:var(--surface);font:400 1rem/1.5 'Source Sans 3',system-ui,sans-serif;box-sizing:border-box;}.ds-reader {
  --surface: var(--parchment);
  --ink: var(--night);
  --muted: #344548;
  --rule: color-mix(in srgb, var(--night) 25%, var(--parchment));
  --focus: var(--night);
  padding: 1.75rem 2rem 4rem;
  color: var(--ink);
  background: var(--surface);
  color-scheme: light;
  scrollbar-color: var(--muted) var(--surface);
}
.ds-reader { max-width: 68ch; margin-inline: auto; font-size: 1.0625rem; line-height: 1.7; }
.ds-note-header { margin-bottom: 2.5rem; padding-bottom: 1.25rem; border-bottom: 1px solid var(--rule); }
.ds-note-identity { width: fit-content; max-width: 100%; margin: 0; font: 400 clamp(1.25rem, 1.8vw, 1.5rem)/1.5 'Libre Baskerville', Georgia, serif; letter-spacing: -.02em; overflow-wrap: anywhere; }
.ds-note-path { margin: .5rem 0 0; color: var(--muted); font-size: .875rem; line-height: 1.5; overflow-wrap: anywhere; }
.ds-formatting { margin-top: .75rem; color: var(--muted); font-size: .875rem; line-height: 1.5; }
.ds-formatting summary { width: fit-content; max-width: 100%; min-height: 44px; padding-block: .625rem; cursor: pointer; }
.ds-formatting p { max-width: 60ch; margin: .25rem 0 1rem; }
.ds-markdown { overflow-wrap: anywhere; }
.ds-markdown p { margin: 0 0 1.4em; }
.ds-markdown h2, .ds-markdown h3, .ds-markdown h4,
.ds-markdown h5, .ds-markdown h6 { margin: 1.8em 0 .65em; font: 400 1.0625rem/1.4 'Libre Baskerville', Georgia, serif; letter-spacing: -.02em; text-wrap: balance; }
.ds-markdown .markdown-h1 { font-size: 1.75rem; }
.ds-markdown code { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: .875em; }
.ds-markdown pre {
  max-width: 100%;
  overflow: auto;
  margin: 1.4em 0;
  padding: 1rem;
  border: 1px solid var(--rule);
  font-size: .9375rem;
  line-height: 1.6;
  white-space: pre;
  overflow-wrap: normal;
  scrollbar-color: var(--muted) var(--surface);
  scrollbar-width: thin;
}
.ds-markdown pre code { font-size: inherit; }
.ds-table-scroll { max-width: 100%; overflow-x: auto; margin: 1.4em 0; scrollbar-color: var(--muted) var(--surface); scrollbar-width: thin; }
.ds-markdown table { width: 100%; border-collapse: collapse; font-size: 1rem; }
.ds-markdown th, .ds-markdown td { min-width: 8rem; padding: .625rem .875rem; border-bottom: 1px solid var(--rule); text-align: left; vertical-align: top; }.ds-markdown h2{margin-top:0;font-size:1.75rem}.ds-reader :focus-visible{outline:2px solid var(--night);outline-offset:4px}.ds-task{list-style:none}.ds-task input{accent-color:var(--night)}

.ds-recall-state{--night:#031315;--parchment:#fef6e1;--lantern:#efb83f;--horizon:#5e8bd6;--surface:var(--night);--ink:var(--parchment);--muted:#d5d3c5;--rule:color-mix(in srgb,var(--parchment) 27%,var(--night));--focus:var(--horizon);color:var(--ink);background:var(--surface);font:400 1rem/1.5 'Source Sans 3',system-ui,sans-serif;box-sizing:border-box;}.ds-recall-state { max-width: 60ch; }
.ds-recall-state h2 { font-size: 1.125rem; }
.ds-recall-state p { margin: .5rem 0 0; }
.ds-recall-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  max-width: 100%;
  padding: .5rem .875rem;
  border: 1px solid var(--ink);
  border-radius: 4px;
  color: var(--ink);
  background: var(--surface);
  cursor: pointer;
}
.ds-recall-button:hover { color: var(--surface); background: var(--ink); }
.ds-recall-button:active { color: var(--night); background: var(--lantern); }.ds-recall-state h2{margin:0}.ds-recall-button{margin-top:1.25rem;font:inherit}.ds-recall-button:focus-visible{outline:2px solid var(--focus);outline-offset:4px}

